#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n, a, b;
    cin >> n >> a >> b;

    if (a > b) swap(a, b);

    int round = 1;
    while (true) {
        if ((a + 1) / 2 == (b + 1) / 2) {
            if (n == 2)
                cout << "Final!\n";
            else
                cout << round << '\n';
            break;
        }

        a = (a + 1) / 2;
        b = (b + 1) / 2;
        n /= 2;
        ++round;
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n, a, b;
    cin >> n >> a >> b;

    int round = 0;
    while (a != b) {
        a = (a + 1) / 2;
        b = (b + 1) / 2;
        n /= 2;
        ++round;
    }

    if (n == 1)
        cout << "Final!\n";
    else
        cout << round << '\n';

    return 0;
}

