#include <algorithm>
using namespace std;

int main() {
    int n, a, b;
    cin >> n >> a >> b;

    int totalRounds = 0;
    for (int players = n; players > 1; players /= 2)
        ++totalRounds;

    int round = 1;
    while ((a + 1) / 2 != (b + 1) / 2) {
        a = (a + 1) / 2;
        b = (b + 1) / 2;
        ++round;
    }

    if (round == totalRounds)
        cout << "Final!\n";
    else
        cout << round << '\n';

    return 0;
}

